import Foundation

/// The case in SBAR form (Situation, Background, Assessment,
/// Recommendation), generated by mmFinalizeCase. Nil on cases finalized
/// before SBAR existed.
struct SBARSummary: Codable, Hashable {
    let situation: String
    let background: String
    let assessment: String
    let recommendation: String
}
